// Generated by Claude Code
package ui;

import grading.assessment.AssessmentDefinition;
import grading.progress.GradingStatus;
import grading.progress.ProgressSnapshot;
import grading.progress.StudentProgress;
import grading.scoring.Marks;
import java.util.List;
import javafx.scene.control.Label;
import javafx.scene.layout.HBox;
import javafx.scene.layout.Priority;
import javafx.scene.layout.VBox;

/** The four numbers a marker checks first: how many are graded, the class average, auto-fixes and reviews. */
final class StatTiles {

    private static final double SPACING = 12;
    private static final String NO_VALUE = "—";
    private static final String ATTENTION = "stat-attention";

    private final Label graded = new Label(NO_VALUE);
    private final Label average = new Label(NO_VALUE);
    private final Label autoFixed = new Label(NO_VALUE);
    private final Label toCheck = new Label(NO_VALUE);
    private final HBox view = new HBox(SPACING, tile("Graded", graded), tile("Class average", average),
            tile("Auto-fixed", autoFixed), tile("Need review", toCheck));

    StatTiles() {
        view.getStyleClass().add("stat-tiles");
        toCheck.setId("needReviewCount");
    }

    HBox view() {
        return view;
    }

    void update(ProgressSnapshot snapshot) {
        List<StudentProgress> students = snapshot.students();
        List<StudentProgress> done = students.stream()
                .filter(student -> student.finished() && student.status() != GradingStatus.SKIPPED)
                .toList();
        final long checking = students.stream().filter(student -> student.status().needsAttention()).count();
        graded.setText(students.isEmpty() ? NO_VALUE : done.size() + "/" + students.size());
        average.setText(done.isEmpty() ? NO_VALUE : Marks.outOf(
                done.stream().mapToDouble(StudentProgress::total).average().orElse(0),
                AssessmentDefinition.totalMarks()));
        autoFixed.setText(students.isEmpty() ? NO_VALUE
                : String.valueOf(students.stream().filter(StudentProgress::formatFixed).count()));
        toCheck.setText(students.isEmpty() ? NO_VALUE : String.valueOf(checking));
        toCheck.getStyleClass().remove(ATTENTION);
        if (checking > 0) {
            toCheck.getStyleClass().add(ATTENTION);
        }
    }

    private static VBox tile(String title, Label value) {
        Label name = new Label(title);
        name.getStyleClass().add("stat-name");
        value.getStyleClass().add("stat-value");
        VBox tile = new VBox(2, name, value);
        tile.getStyleClass().add("stat-tile");
        HBox.setHgrow(tile, Priority.ALWAYS);
        tile.setMaxWidth(Double.MAX_VALUE);
        return tile;
    }
}
